// Server configuration: command-line flags take precedence over environment
// variables (SYNCBOX_DATA_DIR / SYNCBOX_PORT), which take precedence over defaults.

export const DEFAULT_PORT = 8080;

export const USAGE = `Usage: syncbox-server --data-dir <path> [--port <n>]

Options:
  --data-dir <path>  Directory where blobs are stored (required).
                     Env: SYNCBOX_DATA_DIR
  --port <n>         TCP port to listen on, 1-65535 (default: ${DEFAULT_PORT}).
                     Env: SYNCBOX_PORT
  -h, --help         Show this help and exit.`;

export class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ConfigError';
  }
}

const FLAGS = new Set(['--data-dir', '--port']);

/**
 * Parses server configuration.
 *
 * @param {string[]} argv  arguments without the node binary and script path
 * @param {Record<string, string | undefined>} env
 * @returns {{ help: true } | { help: false, dataDir: string, port: number }}
 * @throws {ConfigError} on missing or invalid values
 */
export function parseConfig(argv, env = {}) {
  const flags = {};

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    if (arg === '-h' || arg === '--help') {
      return { help: true };
    }

    let name = arg;
    let value;
    const eq = arg.indexOf('=');
    if (arg.startsWith('--') && eq !== -1) {
      name = arg.slice(0, eq);
      value = arg.slice(eq + 1);
    }

    if (!FLAGS.has(name)) {
      throw new ConfigError(`unknown argument: ${arg}`);
    }

    if (value === undefined) {
      if (i + 1 >= argv.length) {
        throw new ConfigError(`${name} requires a value`);
      }
      value = argv[++i];
    }

    flags[name] = value;
  }

  const dataDir = pick(flags['--data-dir'], env.SYNCBOX_DATA_DIR);
  if (dataDir === undefined) {
    throw new ConfigError('data directory is required: pass --data-dir <path> or set SYNCBOX_DATA_DIR');
  }

  const rawPort = pick(flags['--port'], env.SYNCBOX_PORT);
  const port = rawPort === undefined ? DEFAULT_PORT : parsePort(rawPort);

  return { help: false, dataDir, port };
}

// Empty strings count as "not set" so that `SYNCBOX_PORT= run-server ...`
// falls through to the default instead of failing.
function pick(...candidates) {
  return candidates.find((v) => v !== undefined && v !== '');
}

function parsePort(raw) {
  if (!/^\d+$/.test(raw)) {
    throw new ConfigError(`invalid port: ${JSON.stringify(raw)} (expected an integer 1-65535)`);
  }
  const port = Number(raw);
  if (port < 1 || port > 65535) {
    throw new ConfigError(`invalid port: ${raw} (expected an integer 1-65535)`);
  }
  return port;
}
#!/usr/bin/env node
// Entry point: syncbox-server --data-dir <path> [--port <n>]
// Runs in the foreground until SIGINT/SIGTERM.

import fs from 'node:fs/promises';
import path from 'node:path';

import { ConfigError, USAGE, parseConfig } from './config.js';
import { createServer } from './server.js';

const EXIT_USAGE = 2;

async function main() {
  let config;
  try {
    config = parseConfig(process.argv.slice(2), process.env);
  } catch (err) {
    if (err instanceof ConfigError) {
      console.error(`syncbox-server: ${err.message}\n\n${USAGE}`);
      process.exit(EXIT_USAGE);
    }
    throw err;
  }

  if (config.help) {
    console.log(USAGE);
    return;
  }

  const dataDir = path.resolve(config.dataDir);
  try {
    await prepareDataDir(dataDir);
  } catch (err) {
    console.error(`syncbox-server: data directory ${dataDir} is not usable: ${err.message}`);
    process.exit(1);
  }

  const server = createServer({ dataDir });

  server.on('error', (err) => {
    console.error(`syncbox-server: cannot listen on port ${config.port}: ${err.message}`);
    process.exit(1);
  });

  server.listen(config.port, () => {
    console.log(`syncbox-server listening on port ${config.port}, data dir ${dataDir}`);
  });

  const shutdown = (signal) => {
    console.log(`syncbox-server: received ${signal}, shutting down`);
    server.close(() => process.exit(0));
    // Don't let idle keep-alive connections hold the process open.
    server.closeIdleConnections();
    setTimeout(() => process.exit(0), 5000).unref();
  };
  process.once('SIGINT', shutdown);
  process.once('SIGTERM', shutdown);
}

async function prepareDataDir(dir) {
  await fs.mkdir(dir, { recursive: true });
  const stat = await fs.stat(dir);
  if (!stat.isDirectory()) {
    throw new Error('not a directory');
  }
  await fs.access(dir, fs.constants.R_OK | fs.constants.W_OK | fs.constants.X_OK);
}

main().catch((err) => {
  console.error('syncbox-server: fatal error:', err);
  process.exit(1);
});
import http from 'node:http';

/**
 * Creates the Syncbox HTTP server (not yet listening).
 *
 * @param {{ dataDir: string }} options
 * @returns {http.Server}
 */
export function createServer({ dataDir }) {
  const server = http.createServer((req, res) => {
    try {
      route(req, res, { dataDir });
    } catch (err) {
      console.error('unhandled error while serving %s %s:', req.method, req.url, err);
      if (!res.headersSent) {
        sendJson(res, 500, { error: 'internal server error' });
      } else {
        res.destroy();
      }
    }
  });
  return server;
}

// `ctx` carries server-wide state (dataDir) for the blob handlers.
// eslint-disable-next-line no-unused-vars
function route(req, res, ctx) {
  const path = pathOf(req.url);

  if (path === '/healthz') {
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      res.setHeader('Allow', 'GET, HEAD');
      return sendJson(res, 405, { error: 'method not allowed' });
    }
    return sendJson(res, 200, { status: 'ok' });
  }

  return sendJson(res, 404, { error: 'not found' });
}

// Raw path without the query string. Deliberately not using `new URL()`:
// it would normalise away things like `..` segments that later handlers
// must see verbatim in order to reject them.
function pathOf(rawUrl = '/') {
  const q = rawUrl.indexOf('?');
  return q === -1 ? rawUrl : rawUrl.slice(0, q);
}

function sendJson(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(res.req.method === 'HEAD' ? undefined : payload);
}
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { ConfigError, DEFAULT_PORT, parseConfig } from '../src/config.js';

describe('parseConfig', () => {
  it('reads --data-dir and --port flags', () => {
    assert.deepEqual(parseConfig(['--data-dir', '/srv/data', '--port', '9000'], {}), {
      help: false,
      dataDir: '/srv/data',
      port: 9000,
    });
  });

  it('accepts --flag=value form', () => {
    assert.deepEqual(parseConfig(['--data-dir=/srv/data', '--port=9000'], {}), {
      help: false,
      dataDir: '/srv/data',
      port: 9000,
    });
  });

  it('defaults port to 8080', () => {
    assert.equal(DEFAULT_PORT, 8080);
    assert.equal(parseConfig(['--data-dir', '/srv/data'], {}).port, 8080);
  });

  it('falls back to SYNCBOX_DATA_DIR and SYNCBOX_PORT', () => {
    const env = { SYNCBOX_DATA_DIR: '/env/data', SYNCBOX_PORT: '7000' };
    assert.deepEqual(parseConfig([], env), { help: false, dataDir: '/env/data', port: 7000 });
  });

  it('prefers flags over environment variables', () => {
    const env = { SYNCBOX_DATA_DIR: '/env/data', SYNCBOX_PORT: '7000' };
    assert.deepEqual(parseConfig(['--data-dir', '/flag/data', '--port', '9000'], env), {
      help: false,
      dataDir: '/flag/data',
      port: 9000,
    });
  });

  it('mixes flag and environment sources', () => {
    assert.deepEqual(parseConfig(['--port', '9000'], { SYNCBOX_DATA_DIR: '/env/data' }), {
      help: false,
      dataDir: '/env/data',
      port: 9000,
    });
  });

  it('treats empty environment variables as unset', () => {
    assert.throws(() => parseConfig([], { SYNCBOX_DATA_DIR: '' }), ConfigError);
    assert.equal(parseConfig(['--data-dir', '/d'], { SYNCBOX_PORT: '' }).port, 8080);
  });

  it('requires a data directory', () => {
    assert.throws(() => parseConfig([], {}), { name: 'ConfigError', message: /data directory is required/ });
    assert.throws(() => parseConfig(['--port', '9000'], {}), ConfigError);
  });

  it('rejects a flag without a value', () => {
    assert.throws(() => parseConfig(['--data-dir'], {}), { message: /--data-dir requires a value/ });
    assert.throws(() => parseConfig(['--data-dir', '/d', '--port'], {}), { message: /--port requires a value/ });
  });

  for (const bad of ['abc', '-1', '0', '65536', '80.5', ' 80', '1e3', '0x50']) {
    it(`rejects invalid port ${JSON.stringify(bad)}`, () => {
      assert.throws(() => parseConfig(['--data-dir', '/d', '--port', bad], {}), { message: /invalid port/ });
      assert.throws(() => parseConfig(['--data-dir', '/d'], { SYNCBOX_PORT: bad }), { message: /invalid port/ });
    });
  }

  it('accepts boundary ports', () => {
    assert.equal(parseConfig(['--data-dir', '/d', '--port', '1'], {}).port, 1);
    assert.equal(parseConfig(['--data-dir', '/d', '--port', '65535'], {}).port, 65535);
  });

  it('rejects unknown arguments', () => {
    assert.throws(() => parseConfig(['--data-dir', '/d', '--verbose'], {}), { message: /unknown argument: --verbose/ });
    assert.throws(() => parseConfig(['positional'], {}), { message: /unknown argument/ });
  });

  it('recognises --help', () => {
    assert.deepEqual(parseConfig(['--help'], {}), { help: true });
    assert.deepEqual(parseConfig(['-h'], {}), { help: true });
  });
});
// End-to-end tests of the server entry point: spawns `node src/server-main.js`
// as a real process and talks to it over HTTP.

import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import fs from 'node:fs/promises';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { after, before, describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';

const MAIN = fileURLToPath(new URL('../src/server-main.js', import.meta.url));

// Environment without any SYNCBOX_* variables inherited from the test runner.
const CLEAN_ENV = Object.fromEntries(Object.entries(process.env).filter(([k]) => !k.startsWith('SYNCBOX_')));

function startServer(args, env = {}) {
  const child = spawn(process.execPath, [MAIN, ...args], {
    env: { ...CLEAN_ENV, ...env },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let stdout = '';
  let stderr = '';
  child.stdout.on('data', (d) => (stdout += d));
  child.stderr.on('data', (d) => (stderr += d));
  const exited = new Promise((resolve) => child.on('exit', (code, signal) => resolve({ code, signal })));
  return { child, exited, output: () => ({ stdout, stderr }) };
}

async function freePort() {
  const srv = net.createServer();
  await new Promise((resolve) => srv.listen(0, '127.0.0.1', resolve));
  const { port } = srv.address();
  await new Promise((resolve) => srv.close(resolve));
  return port;
}

async function waitForHealthy(port, proc, timeoutMs = 10_000) {
  const deadline = Date.now() + timeoutMs;
  let lastError;
  while (Date.now() < deadline) {
    if (proc.child.exitCode !== null) {
      throw new Error(`server exited early: ${JSON.stringify(proc.output())}`);
    }
    try {
      const res = await fetch(`http://127.0.0.1:${port}/healthz`);
      await res.body?.cancel();
      if (res.status === 200) return;
    } catch (err) {
      lastError = err;
    }
    await new Promise((r) => setTimeout(r, 50));
  }
  throw new Error(`server did not become healthy on port ${port}: ${lastError}`);
}

async function stop(proc) {
  if (proc.child.exitCode === null && proc.child.signalCode === null) {
    proc.child.kill('SIGTERM');
  }
  return proc.exited;
}

describe('server-main', () => {
  let tmp;

  before(async () => {
    tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'syncbox-test-'));
  });

  after(async () => {
    await fs.rm(tmp, { recursive: true, force: true });
  });

  it('serves /healthz on the port given by --port', async () => {
    const port = await freePort();
    const proc = startServer(['--data-dir', path.join(tmp, 'flags'), '--port', String(port)]);
    try {
      await waitForHealthy(port, proc);
    } finally {
      await stop(proc);
    }
  });

  it('is configurable through SYNCBOX_DATA_DIR and SYNCBOX_PORT', async () => {
    const port = await freePort();
    const proc = startServer([], { SYNCBOX_DATA_DIR: path.join(tmp, 'env'), SYNCBOX_PORT: String(port) });
    try {
      await waitForHealthy(port, proc);
    } finally {
      await stop(proc);
    }
  });

  it('creates a missing data directory', async () => {
    const dataDir = path.join(tmp, 'nested', 'does', 'not', 'exist');
    const port = await freePort();
    const proc = startServer(['--data-dir', dataDir, '--port', String(port)]);
    try {
      await waitForHealthy(port, proc);
      assert.ok((await fs.stat(dataDir)).isDirectory());
    } finally {
      await stop(proc);
    }
  });

  it('exits cleanly with code 0 on SIGTERM', async () => {
    const port = await freePort();
    const proc = startServer(['--data-dir', path.join(tmp, 'sigterm'), '--port', String(port)]);
    await waitForHealthy(port, proc);
    const { code } = await stop(proc);
    assert.equal(code, 0);
  });

  it('exits with code 2 and a message when --data-dir is missing', async () => {
    const proc = startServer(['--port', '8080']);
    const { code } = await proc.exited;
    assert.equal(code, 2);
    assert.match(proc.output().stderr, /data directory is required/);
  });

  it('exits with code 2 on an invalid port', async () => {
    const proc = startServer(['--data-dir', tmp, '--port', 'not-a-port']);
    const { code } = await proc.exited;
    assert.equal(code, 2);
    assert.match(proc.output().stderr, /invalid port/);
  });

  it('fails when the data directory path is a regular file', async () => {
    const file = path.join(tmp, 'regular-file');
    await fs.writeFile(file, 'x');
    const proc = startServer(['--data-dir', file, '--port', String(await freePort())]);
    const { code } = await proc.exited;
    assert.equal(code, 1);
    assert.match(proc.output().stderr, /data directory .* is not usable/);
  });

  it('fails when the port is already in use', async () => {
    const blocker = net.createServer();
    await new Promise((resolve) => blocker.listen(0, resolve));
    try {
      const port = blocker.address().port;
      const proc = startServer(['--data-dir', tmp, '--port', String(port)]);
      const { code } = await proc.exited;
      assert.equal(code, 1);
      assert.match(proc.output().stderr, /cannot listen on port/);
    } finally {
      await new Promise((resolve) => blocker.close(resolve));
    }
  });

  it('prints usage on --help', async () => {
    const proc = startServer(['--help']);
    const { code } = await proc.exited;
    assert.equal(code, 0);
    assert.match(proc.output().stdout, /Usage: syncbox-server/);
  });
});
import assert from 'node:assert/strict';
import { after, before, describe, it } from 'node:test';

import { createServer } from '../src/server.js';

describe('HTTP server', () => {
  let server;
  let baseUrl;

  before(async () => {
    server = createServer({ dataDir: '/nonexistent-unused-by-healthz' });
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    baseUrl = `http://127.0.0.1:${server.address().port}`;
  });

  after(async () => {
    server.closeAllConnections();
    await new Promise((resolve) => server.close(resolve));
  });

  it('GET /healthz returns 200', async () => {
    const res = await fetch(`${baseUrl}/healthz`);
    assert.equal(res.status, 200);
    assert.deepEqual(await res.json(), { status: 'ok' });
  });

  it('GET /healthz ignores the query string', async () => {
    const res = await fetch(`${baseUrl}/healthz?probe=1`);
    assert.equal(res.status, 200);
    await res.body?.cancel();
  });

  it('HEAD /healthz returns 200 without a body', async () => {
    const res = await fetch(`${baseUrl}/healthz`, { method: 'HEAD' });
    assert.equal(res.status, 200);
    assert.equal(await res.text(), '');
  });

  it('rejects other methods on /healthz with 405', async () => {
    const res = await fetch(`${baseUrl}/healthz`, { method: 'POST' });
    assert.equal(res.status, 405);
    assert.equal(res.headers.get('allow'), 'GET, HEAD');
    await res.body?.cancel();
  });

  it('returns 404 for unknown paths', async () => {
    const res = await fetch(`${baseUrl}/no-such-endpoint`);
    assert.equal(res.status, 404);
    await res.body?.cancel();
  });
});

