      assert.deepEqual((await fs.readdir(dataDir)).sort(), ['tmp']);
      assert.deepEqual(await fs.readdir(path.join(dataDir, 'tmp')), []);
      assert.deepEqual(await fs.readdir(tmp).then((names) => names.filter((n) => !n.startsWith('data-'))), []);
